#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Ticket 01 (.scratch/complete-phases-5-7/issues/01-manual-setup.md): every manual step
# needed before the live check (ticket 16), the manual live path testing (ticket 17)
# and the real model comparison (ticket 18).
# Run from anywhere: ./scripts/setup_wizard.sh. Values go to .env only (no CI here).

TOTAL_STAGES=11

cd "$(dirname "$0")/.."

# envval KEY: the .env value without surrounding quotes (older lines were written as KEY="value").
envval() {
  local v; v=$(_existing "$1" || true)
  v="${v%\"}"; v="${v#\"}"
  printf '%s' "$v"
}

# ms365 ARGS...: the pinned MS365 server with the agent's own tool list and credentials,
# so the Graph scopes it asks for match exactly what the agent will request.
ms365() {
  MS365_MCP_CLIENT_ID="$(envval MS365_MCP_CLIENT_ID)" \
  MS365_MCP_TENANT_ID="$(envval MS365_MCP_TENANT_ID)" \
    npx -y "$MS365_PACKAGE" --enabled-tools "$MS365_PATTERN" "$@"
}

# ping_model PROVIDER:MODEL: one tiny live call through the agent's own model factory.
ping_model() {
  uv run python - "$1" <<'PY'
import sys
from agent.chat_model import create_chat_model
reply = create_chat_model(sys.argv[1]).invoke("Reply with the single word OK.")
print("  model replied:", str(reply.content)[:60])
PY
}

banner "ITtopia agent: live setup (ticket 01)"

# ── 1 ────────────────────────────────────────────────────────────────────────
stage "Preflight"
say "Checking tools and backing up .env before anything changes."
for cmd in uv npx docker curl; do
  if command -v "$cmd" >/dev/null 2>&1; then step "$cmd found"
  else warn "$cmd is missing: install it, then re-run"; exit 1; fi
done
branch=$(git rev-parse --abbrev-ref HEAD)
[[ "$branch" == "feat/complete-phases-5-7" ]] || warn "you're on '$branch'; the live code is on feat/complete-phases-5-7"
uv sync -q
if [[ -f "$ENV_FILE" ]]; then
  backup=".env.bak-$(date +%Y%m%d-%H%M%S)"
  cp "$ENV_FILE" "$backup"
  step "backed up .env → $backup (gitignored)"
fi
MS365_PACKAGE=$(uv run python -c "from agent.tools.ms365_mcp import PACKAGE; print(PACKAGE)")
MS365_PATTERN=$(uv run python -c "from agent.tools.ms365_mcp import enabled_tools_pattern; print(enabled_tools_pattern())")
note "MS365 server: $MS365_PACKAGE"
pause

# ── 2 ────────────────────────────────────────────────────────────────────────
stage "Models: your Claude subscription, and a Google key for embeddings"
say "The agent's chat model runs on your Claude subscription through Claude Code: no chat API key."
CLAUDE_BIN=$(envval CLAUDE_CODE_BINARY); CLAUDE_BIN=${CLAUDE_BIN:-claude}
until uv run python -c "import sys; from agent.auth.claude_code import check_claude_code_login; check_claude_code_login(sys.argv[1])" "$CLAUDE_BIN"; do
  warn "Claude Code is missing or not logged in with your Claude subscription (see above)"
  step "Install Claude Code if needed, then run 'claude auth login' in another terminal."
  confirm "Logged in? Check again?" || { SKIPPED+=("Claude Code login: run 'claude auth login'"); break; }
done
write_env MODEL_NAME "claude_code:claude-sonnet-5-5"
write_env EVAL_JUDGE_MODEL "claude_code:claude-opus-5-5"
say "GOOGLE_API_KEY is still required: the memory layer embeds with it."
note "Use a key from a Google project with billing turned off, so it can never be charged."
open_url "https://aistudio.google.com/apikey"
GOOGLE_API_KEY=""
until [[ -n "$GOOGLE_API_KEY" ]]; do ask_secret GOOGLE_API_KEY "Paste the Google API key:"; done
write_env GOOGLE_API_KEY "$GOOGLE_API_KEY"
if confirm "Test Gemini as a chat model too? (skip if you use your Claude subscription)"; then
  ping_model "google_genai:gemini-3.8-flash" \
    || { warn "the Gemini call failed (see above)"; SKIPPED+=("Gemini chat test failed: check GOOGLE_API_KEY"); }
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────────
stage "Anthropic: API key for the Claude comparison (optional)"
say "Only for anthropic: models, e.g. comparing against the Claude API."
if confirm "Set up an Anthropic API key? (skip if you use your Claude subscription)"; then
  open_url "https://console.anthropic.com/settings/keys"
  step "Settings → API keys → Create key; name it e.g. 'ittopia-agent'; copy it (shown once)."
  ask_secret ANTHROPIC_API_KEY "Paste the Anthropic API key:"
  write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
  ping_model "anthropic:claude-sonnet-5-5" \
    || { warn "the Claude call failed (see above)"; SKIPPED+=("Anthropic key test failed: check ANTHROPIC_API_KEY and billing"); }
fi
pause

# ── 4 ────────────────────────────────────────────────────────────────────────
stage "Informer: API key and security code"
say "The agent's Informer server is read-only, but the key itself can write: keep it secret."
open_url "https://app.informer.eu/settings/api/"
step "Settings → API keys → create a new key; copy it."
ask_secret INFORMER_API_KEY "Paste the Informer API key:"
open_url "https://app.informer.eu/settings/account/"
step "Account settings → copy the security code (company code)."
ask_secret INFORMER_SECURITY_CODE "Paste the security code:"
write_env INFORMER_API_KEY "$INFORMER_API_KEY"
write_env INFORMER_SECURITY_CODE "$INFORMER_SECURITY_CODE"
say "Testing with one read-only request (GET /relations, 1 record)…"
if uv run python - <<'PY'
import httpx
from informer_mcp.config import InformerSettings
s = InformerSettings()
r = httpx.get(f"{s.base_url}/relations", params={"records": 1}, timeout=30,
              headers={"Apikey": s.api_key, "Securitycode": s.security_code})
print("  Informer answered HTTP", r.status_code,
      "| daily quota left:", r.headers.get("X-DailyLimit-Remaining", "n/a"))
raise SystemExit(0 if r.status_code == 200 else 1)
PY
then step "Informer credentials work"
else warn "Informer rejected the request"; SKIPPED+=("Informer test failed: re-run stage 4 with the right key/code"); fi
pause

# ── 5 ────────────────────────────────────────────────────────────────────────
stage "Informer: e-mail upload of Purchase invoices (optional)"
say "Uploads need two addresses: the Informer incoming address and the Invoice mailbox it is sent from."
say "Without both, the agent has no upload tools. Skip this to keep it that way."
warn "The incoming address works like a write key to the books: never share it or commit it."
if confirm "Set up the Informer e-mail upload?"; then
  open_url "https://app.informer.eu/settings/email/"
  step "E-mail settings → copy the address Informer reads Purchase invoices from (the incoming address)."
  ask_secret INFORMER_INCOMING_ADDRESS "Paste the Informer incoming address:"
  ask INFORMER_INVOICE_MAILBOX "Invoice mailbox address (the ITtopia shared mailbox the e-mails are sent from):"
  if [[ -n "$INFORMER_INCOMING_ADDRESS" && -n "$INFORMER_INVOICE_MAILBOX" ]]; then
    write_env INFORMER_INCOMING_ADDRESS "$INFORMER_INCOMING_ADDRESS"
    write_env INFORMER_INVOICE_MAILBOX "$INFORMER_INVOICE_MAILBOX"
  else
    warn "an address was empty, so neither was saved"
    SKIPPED+=("Informer e-mail upload: re-run stage 5 with both addresses")
  fi
fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────────
stage "Azure app: allow saving Drafts and sending from the Invoice mailbox"
say "Your own app registration needs two more delegated Graph permissions: Mail.ReadWrite to save"
say "Drafts, and Mail.Send.Shared so the Invoice mailbox can send Purchase invoices to Informer."
say "Mail.Send (sending as you) is never added."
ask MS365_MCP_CLIENT_ID "Application (client) ID:"
ask MS365_MCP_TENANT_ID "Directory (tenant) ID:"
MS365_MCP_CLIENT_ID="${MS365_MCP_CLIENT_ID//\"/}"; MS365_MCP_TENANT_ID="${MS365_MCP_TENANT_ID//\"/}"
write_env MS365_MCP_CLIENT_ID "$MS365_MCP_CLIENT_ID"
write_env MS365_MCP_TENANT_ID "$MS365_MCP_TENANT_ID"
open_url "https://portal.azure.com/#view/Microsoft_AAD_RegisteredApps/ApplicationMenuBlade/~/CallAnAPI/appId/$MS365_MCP_CLIENT_ID"
step "API permissions → Add a permission → Microsoft Graph → Delegated permissions."
step "Search 'Mail.ReadWrite' → tick it → Add permissions."
step "Again: search 'Mail.Send.Shared' → tick it → Add permissions (without it every upload fails with a Graph 403)."
step "Click 'Grant admin consent for <ITtopia>' → Yes. Do NOT add Mail.Send."
step "Sending is limited to the Invoice mailbox by an Exchange mail-flow rule (Exchange admin center →"
step "  Mail flow → Rules): mail from the Invoice mailbox to anyone but the Informer incoming address is rejected."
step "Then Authentication (left menu) → 'Allow public client flows' must be Yes (device-code login)."
pause "Done in the portal? Press Enter to list what the server will request"
say "Graph permissions the agent's tool set needs:"
ms365 --list-permissions || warn "couldn't list permissions (see above)"
warn "Check: Mail.ReadWrite is listed; Mail.Send is NOT. Each listed one must be granted above."
warn "Mail.Send.Shared is not in this list (the Informer server's own MS365 server uses it): check it is granted too."
confirm "Does the list look right?" || SKIPPED+=("Azure permissions: re-check API permissions vs --list-permissions")
pause

# ── 7 ────────────────────────────────────────────────────────────────────────
stage "Microsoft 365: one-time login"
say "Logging in with the pinned server version and the agent's tool list."
step "It prints a URL and a code: open the URL, enter the code, sign in with the ITtopia account."
step "When macOS asks for keychain access for node, choose 'Always Allow'."
pause "Press Enter to start the login"
if ms365 --login; then step "login finished"
else warn "login failed (see above)"; SKIPPED+=("MS365 login: re-run stage 7"); fi
say "Verifying the cached login…"
ms365 --verify-login || { warn "verify-login failed"; SKIPPED+=("MS365 verify-login failed"); }
